{
  "scenario_id": "sc-4a7f9e",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "Death",
      "years": [2021, 2022],
      "pattern": "shock",
      "direction": "increase",
      "magnitude": "~+0.30 to +0.35 A/E (7-13σ above Poisson expectation)",
      "confidence": 0.95,
      "evidence": [
        "ae_death_by_year.csv: A/E jumps from 0.952 in 2020 to 1.296 (2021) and 1.282 (2022), then reverts to 0.860/0.925 in 2023-2024."
      ],
      "recommended_action": "Investigate 2021-2022 mortality spike (e.g., pandemic impact, specific high-severity events, data/coding errors, or underwriting lapses). If confirmed non-recurring, exclude or weight these years in pricing/valuation; otherwise update mortality assumptions."
    },
    {
      "benefit": "CI",
      "years": [2021, 2022],
      "pattern": "shock",
      "direction": "decrease",
      "magnitude": "~-0.45 to -0.50 A/E drop (12-14σ below Poisson expectation)",
      "confidence": 0.95,
      "evidence": [
        "ae_ci_by_year.csv: A/E falls from 1.114 in 2020 to 0.670 (2021) and 0.654 (2022), returning to ~1.14 in 2023-2024."
      ],
      "recommended_action": "Investigate 2021-2022 CI claim suppression (e.g., reporting lag, pandemic disruption to diagnoses/claims processing, or product change). Note that non-shock years show a persistent A/E of ~1.12-1.15, which may warrant a separate baseline assumption review."
    }
  ]
}

